module freq_divbyfrac(
    input clk, input rst_n,
    output clk_div
);
    // Parameter definitions
    parameter MUL2_DIV_CLK = 7;
    // Internal signals
    reg [3:0] cnt;
    reg clk_div_int;
    reg phase_delay;
    reg phase_advance;
    // Sequential logic for counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
        end else begin
            if (cnt == MUL2_DIV_CLK - 1) begin
                cnt <= 0;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
    // Sequential logic for intermediate divided clock signal
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div_int <= 0;
        end else begin
            if ((cnt >= 0 && cnt <= 3) || (cnt >= 5 && cnt <= 6)) begin
                clk_div_int <= ~clk_div_int;
            end
        end
    end
    // Sequential logic for phase delay and advance generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase_delay <= 0;
            phase_advance <= 0;
        end else begin
            if (cnt == 4) begin
                phase_delay <= clk_div_int;
            end

            if (cnt == 3) begin
                phase_advance <= clk_div_int;
            end
        end
    end
    // Assign final fractional divided clock output
    assign clk_div = clk_div_int | phase_delay | phase_advance;
endmodule
